Record Venta
  Define codigo, cantidad As Integer;
EndRecord

Function valor <- PrecioDe(codigo As Integer)
  Define valor As Integer;
  Switch codigo Do
    1:
      valor <- 3;
    2:
      valor <- 5;
    3:
      valor <- 2;
    4:
      valor <- 1;
    Otherwise:
      valor <- 2;
  EndSwitch
EndFunction

Function nombre <- NombreDe(codigo As Integer)
  Define nombre As String;
  Switch codigo Do
    1:
      nombre <- "Jugo";
    2:
      nombre <- "Sándwich";
    3:
      nombre <- "Alfajor";
    4:
      nombre <- "Agua";
    Otherwise:
      nombre <- "Fruta";
  EndSwitch
EndFunction

Function importe <- Importe(venta As Venta)
  Define importe As Integer;
  importe <- PrecioDe(venta.codigo) * venta.cantidad;
EndFunction

Function grande <- MasDeCinco(monto As Integer)
  Define grande As Boolean;
  grande <- monto > 5;
EndFunction

Function total <- Sumar(a As Integer, b As Integer)
  Define total As Integer;
  total <- a + b;
EndFunction

Function monto <- ConDescuento(total As Integer)
  Define monto As Integer;
  monto <- total - total Div 10;
EndFunction

Function nuevos <- Mapear(ventas As Vector<Venta>, f As Function(Venta) As Integer)
  Define nuevos As Vector<Integer> <- vector();
  For Each venta In ventas Do
    nuevos.append(f(venta));
  EndFor
EndFunction

Function elegidos <- Filtrar(montos As Vector<Integer>, condicion As Function(Integer) As Boolean)
  Define elegidos As Vector<Integer> <- vector();
  For Each monto In montos Do
    If condicion(monto) Then
      elegidos.append(monto);
    EndIf
  EndFor
EndFunction

Function acumulado <- Reducir(montos As Vector<Integer>, f As Function(Integer, Integer) As Integer, inicial As Integer)
  Define acumulado As Integer <- inicial;
  For Each monto In montos Do
    acumulado <- f(acumulado, monto);
  EndFor
EndFunction

Function contar <- UnidadesDel(codigo As Integer)
  Define contar As Function(Venta) As Integer <- Function(venta As Venta) As Integer
    If venta.codigo = codigo Then
      Return venta.cantidad;
    EndIf
    Return 0;
  EndFunction;
EndFunction

Function estrella <- Estrella(ventas As Vector<Venta>)
  Define estrella As String <- "Ninguno";
  Define mejores As Integer <- 0;
  For codigo <- 1 To 5 Do
    Define unidades As Integer <- Reducir(Mapear(ventas, UnidadesDel(codigo)), Sumar, 0);
    If unidades > mejores Then
      mejores <- unidades;
      estrella <- NombreDe(codigo);
    EndIf
  EndFor
EndFunction

Algorithm Reporte
  Define ventas As Vector<Venta> <- vector();
  Define codigo, cantidad As Integer;
  Read codigo;
  While codigo <> 0 Do
    Read cantidad;
    ventas.append(Venta(codigo, cantidad));
    Read codigo;
  EndWhile
  Define importes As Vector<Integer> <- Mapear(ventas, Importe);
  Define total As Integer <- Reducir(importes, Sumar, 0);
  Write "Total: ", total;
  Write "Con descuento: ", ConDescuento(total);
  Write "Ventas de más de 5 pesos: ", Filtrar(importes, MasDeCinco).length();
  Write "Producto estrella: ", Estrella(ventas);
EndAlgorithm
